with latest as (select *, row_number() over (partition by dept_id order by hire_date desc, id) as row_num from employees qualify row_num = 1) select s.id, s.dept_id, s.manager_id, s.job_title, s.salary, s.hire_date, s.level, s.row_num, (select max(e2.salary) from employees e2 where e2.manager_id = s.manager_id) as max_employee_salary from latest s order by dept_id nulls first, hire_date;
